}

'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import Link from 'next/link';

import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { useSettings } from '@/components/SettingsProvider';
import { PUTAWAY_STATUS } from '@modbm/shared';
import SlideOver from '@/components/shared/SlideOver';
import MasterDetailLayout from '@/components/shared/MasterDetailLayout';
import { getErrorMessage } from '@modbm/shared';

interface PutawayLine {
    id: string;
    sourceType: 'goods_receipt' | 'sales_return';
    referenceNumber: string;
    productId: string;
    productName: string;
    productNumber: string;
    quantity: string;
    createdOn: string;
}

interface BinInfo {
    binId: string;
    binNumber: string;
    binType: string;
}

interface PutawayContext {
    primaryBinId: string | null;
    primaryBinNumber: string | null;
    currentQuantity: number;
    availableBins: BinInfo[];
}

export default function PutawayPage() {
    const t = useTranslations('inventory');
    const tCommon = useTranslations('common');
    useDocumentTitle(t('putaway.title'));
    const { app } = useSettings();

    const [locations, setLocations] = useState<any[]>([]);
    const [selectedLocationId, setSelectedLocationId] = useState<string>('');
    const [pendingLines, setPendingLines] = useState<PutawayLine[]>([]);
    const [selectedLine, setSelectedLine] = useState<PutawayLine | null>(null);
    const [loadingLines, setLoadingLines] = useState(false);
    
    // Putaway Form State
    const [context, setContext] = useState<PutawayContext | null>(null);
    const [loadingContext, setLoadingContext] = useState(false);
    const [selectedBinId, setSelectedBinId] = useState<string>('');
    const [binSearch, setBinSearch] = useState<string>('');
    const [newTotalQuantity, setNewTotalQuantity] = useState<string>('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Fetch Locations
    useEffect(() => {
        api.inventoryControllerFindAllLocations({} )
            .then((response) => {
                const res = response.data;
                const locs = res || [];
                setLocations(locs);
                if (locs.length > 0) {
                    const defaultLocId = app?.defaultFulfillmentLocationId || locs[0].locationId;
                    setSelectedLocationId(defaultLocId);
                }
            })
            .catch(err => reportError(err, 'Failed to load locations'));
    }, [app?.defaultFulfillmentLocationId]);

    // Fetch Pending Lines
    useEffect(() => {
        if (!selectedLocationId) return;

        setLoadingLines(true);
        setSelectedLine(null);
        setContext(null);

        api.inventoryControllerGetPendingPutaway({ locationId: selectedLocationId })
            .then(response => {
                const lines = response.data || [];
                setPendingLines(lines as PutawayLine[]);
            })
            .catch(err => reportError(err, 'Failed to load pending lines'))
            .finally(() => setLoadingLines(false));
    }, [selectedLocationId]);

    // Fetch Context for Selected Line
    useEffect(() => {
        if (!selectedLine || !selectedLocationId) {
            setContext(null);
            return;
        }

        setLoadingContext(true);
        setError(null);
        api.inventoryControllerGetPutawayContext({ productId: selectedLine.productId, locationId: selectedLocationId })
            .then((response) => {
                const contextData = response.data ;
                setContext(contextData as unknown as PutawayContext);
                if (contextData.primaryBinId) {
                    setSelectedBinId(contextData.primaryBinId);
                    setBinSearch(contextData.primaryBinNumber || '');
                } else {
                    setSelectedBinId('');
                    setBinSearch('');
                }
                const expectedTotal = contextData.currentQuantity + parseFloat(selectedLine.quantity);
                setNewTotalQuantity(expectedTotal.toString());
            })
            .catch(err => setError(getErrorMessage(err)))
            .finally(() => setLoadingContext(false));
    }, [selectedLine, selectedLocationId]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedLine || !selectedBinId || !newTotalQuantity) return;

        setIsSubmitting(true);
        setError(null);

        try {
            await api.inventoryControllerPutaway({
                putaways: [
                    {
                        lineId: selectedLine.id,
                        sourceType: selectedLine.sourceType,
                        destinationBinId: selectedBinId,
                        quantity: selectedLine.quantity,
                        newTotalQuantity
                    }
                ]
            });

            // Remove from list and reset
            setPendingLines(prev => prev.filter(l => l.id !== selectedLine.id));
            setSelectedLine(null);
            setContext(null);
        } catch (err: unknown) {
            setError(getErrorMessage(err));
        } finally {
            setIsSubmitting(false);
        }
    };

    const actionFormContent = (
        <div className="flex-1 overflow-y-auto p-4 lg:p-6 pb-24 lg:pb-6">
            {!selectedLine ? (
                <div className="flex items-center justify-center h-full text-[var(--text-muted)] text-sm">
                    {t('putaway.selectItemToPutaway')}
                </div>
            ) : loadingContext ? (
                <div className="flex items-center justify-center h-full text-[var(--text-muted)] text-sm">
                    {t('putaway.loadingBinContext')}
                </div>
            ) : context ? (
                <form onSubmit={handleSubmit} className="flex flex-col h-full max-w-md mx-auto">
                    <div className="mb-6 pb-4 border-b border-[var(--border)] flex justify-between items-start">
                        <div>
                            <h3 className="text-lg font-bold text-[var(--accent)]">{selectedLine.productName}</h3>
                            <div className="flex flex-wrap items-center gap-1.5 mt-1 text-sm text-[var(--text-secondary)]">
                                <span className="uppercase tracking-wider">{selectedLine.productNumber}</span>
                                <span className="text-[var(--text-muted)]">ΓÇó</span>
                                <span>{t('putaway.ref', { ref: selectedLine.referenceNumber })}</span>
                            </div>
                        </div>
                        <div className="text-2xl font-bold text-[var(--text-primary)] mt-1">
                            {parseFloat(selectedLine.quantity).toLocaleString()}
                        </div>
                    </div>

                    {error && (
                        <div className="mb-4 p-3 bg-red-50 border border-red-200 text-red-700 text-sm rounded-md flex items-center gap-2">
                            {/* eslint-disable-next-line i18next/no-literal-string */}
                            <span className="material-symbols-outlined text-sm">error</span>
                            {/* eslint-enable i18next/no-literal-string */}
                            {error}
                        </div>
                    )}

                    <div className="space-y-5 flex-1">
                        <div>
                            <label className="block text-xs font-bold text-[var(--text-muted)] uppercase mb-1.5">{t('putaway.destinationBin')}</label>
                            <input
                                type="text"
                                list="available-bins"
                                value={binSearch}
                                onChange={e => {
                                    const val = e.target.value;
                                    setBinSearch(val);
                                    const match = context.availableBins.find(b => b.binNumber === val);
                                    setSelectedBinId(match ? match.binId : '');
                                }}
                                className="w-full px-3 py-2 border border-[var(--border)] rounded-md bg-[var(--bg-card)] text-[var(--text-primary)] focus:outline-none focus:ring-1 focus:ring-[var(--accent)] text-sm"
                                placeholder={t('putaway.searchBins')}
                                required
                            />
                            <datalist id="available-bins">
                                {context.availableBins.map(bin => (
                                    <option key={bin.binId} value={bin.binNumber}>
                                        {bin.binId === context.primaryBinId ? t('putaway.primaryLabel') : ''}
                                    </option>
                                ))}
                            </datalist>
                            
                            {/* Tiles UI */}
                            {(() => {
                                const matchingBins = context.availableBins.filter(b => b.binNumber.toUpperCase().startsWith(binSearch.toUpperCase()));
                                const showTiles = !selectedBinId;
                                
                                let tiles: { label: string; value: string; isFullBin: boolean; binId?: string }[] = [];
                                if (showTiles) {
                                    if (matchingBins.length < 20) {
                                        tiles = matchingBins.map(b => ({
                                            label: b.binNumber,
                                            value: b.binNumber,
                                            isFullBin: true,
                                            binId: b.binId
                                        }));
                                    } else {
                                        const nextCharIndex = binSearch.length;
                                        const prefixSet = new Set<string>();
                                        matchingBins.forEach(b => {
                                            if (b.binNumber.length > nextCharIndex) {
                                                prefixSet.add(b.binNumber.substring(0, nextCharIndex + 1).toUpperCase());
                                            } else {
                                                prefixSet.add(b.binNumber.toUpperCase());
                                            }
                                        });
                                        tiles = Array.from(prefixSet).sort().map(prefix => {
                                            return { label: prefix, value: prefix, isFullBin: false };
                                        });
                                    }
                                }

                                if (!showTiles || tiles.length === 0) return null;

                                return (
                                    <div className="mt-3">
                                        <div className="grid grid-cols-4 sm:grid-cols-5 gap-2">
                                            {tiles.map(tile => (
                                                <button
                                                    key={tile.value}
                                                    type="button"
                                                    onClick={() => {
                                                        setBinSearch(tile.value);
                                                        if (tile.isFullBin && tile.binId) {
                                                            setSelectedBinId(tile.binId);
                                                        }
                                                    }}
                                                    className="h-14 px-1 bg-[var(--bg-secondary)] border border-[var(--border)] rounded-lg flex items-center justify-center text-sm font-bold text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)] hover:border-[var(--accent)] transition-all truncate"
                                                    title={tile.label}
                                                >
                                                    {tile.label}
                                                </button>
                                            ))}
                                        </div>
                                    </div>
                                );
                            })()}

                            {context.primaryBinId && selectedBinId && selectedBinId !== context.primaryBinId && (
                                <p className="mt-2 text-[11px] text-[var(--warning)] flex items-center gap-1">
                                    {/* eslint-disable-next-line i18next/no-literal-string */}
                                    <span className="material-symbols-outlined text-[14px]">warning</span>
                                    {/* eslint-enable i18next/no-literal-string */}
                                    {t('putaway.warningNotPrimary', { bin: context.primaryBinNumber || '' })}
                                </p>
                            )}
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-[var(--text-muted)] uppercase mb-1.5 flex justify-between">
                                <span>{t('putaway.newTotalQuantity')}</span>
                                <span className="text-[10px] font-normal normal-case">{t('putaway.currentStock', { count: context.currentQuantity })}</span>
                            </label>
                            <input
                                type="number"
                                step="0.01"
                                value={newTotalQuantity}
                                onChange={e => setNewTotalQuantity(e.target.value)}
                                className="w-full px-3 py-2 border border-[var(--border)] rounded-md bg-[var(--bg-card)] text-[var(--text-primary)] focus:outline-none focus:ring-1 focus:ring-[var(--accent)] text-sm"
                                required
                            />
                            <p className="mt-1 text-[11px] text-[var(--text-muted)]">
                                {t('putaway.verifyCountDescription')}
                            </p>
                        </div>
                    </div>

                    <div className="pt-4 mt-auto">
                        <button
                            type="submit"
                            disabled={isSubmitting || !selectedBinId || !newTotalQuantity}
                            className="w-full py-2.5 px-4 bg-[var(--accent)] text-white text-sm font-bold rounded-lg hover:brightness-110 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm flex items-center justify-center gap-2"
                        >
                            {isSubmitting ? (
                                <>
                                    {/* eslint-disable-next-line i18next/no-literal-string */}
                                    <span className="material-symbols-outlined animate-spin text-[18px]">sync</span>
                                    {/* eslint-enable i18next/no-literal-string */}
                                    {t('putaway.processing')}
                                </>
                            ) : (
                                <>
                                    {/* eslint-disable-next-line i18next/no-literal-string */}
                                    <span className="material-symbols-outlined text-[18px]">done_all</span>
                                    {/* eslint-enable i18next/no-literal-string */}
                                    {t('putaway.confirmPutaway')}
                                </>
                            )}
                        </button>
                    </div>
                </form>
            ) : null}
        </div>
    );

    return (
        <MasterDetailLayout
            title={t('putaway.title')}
            controls={
                <>
                    <span className="text-sm font-semibold text-[var(--text-muted)]">{tCommon('location')}:</span>
                    <select
                        value={selectedLocationId}
                        onChange={(e) => setSelectedLocationId(e.target.value)}
                        className="input text-sm w-full sm:w-48"
                    >
                        {locations.map(loc => (
                            <option key={loc.locationId} value={loc.locationId}>
                                {loc.code} - {loc.name}
                            </option>
                        ))}
                    </select>
                </>
            }
            masterWidthClass="lg:w-1/2"
            isDetailOpen={!!selectedLine}
            onCloseDetail={() => { setSelectedLine(null); setContext(null); }}
            detailTitle={t('putaway.action')}
            masterPane={
                <>
                    <div className="px-4 py-3 border-b border-[var(--border)] bg-[var(--bg-secondary)] flex justify-between items-center">
                        <h2 className="text-sm font-bold text-[var(--text-primary)] uppercase tracking-wider">{t('putaway.pendingPutaway')}</h2>
                        <span className="bg-[var(--accent)] text-white text-xs font-bold px-2 py-0.5 rounded-full">
                            {pendingLines.length}
                        </span>
                    </div>
                    
                    <div className="flex-1 overflow-y-auto p-2 pb-24 lg:pb-2 bg-[var(--bg-card)] lg:bg-transparent rounded-b-md lg:rounded-none">
                        {loadingLines ? (
                            <div className="flex items-center justify-center h-full text-[var(--text-muted)] text-sm">
                                {tCommon('loading')}
                            </div>
                        ) : pendingLines.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-full text-[var(--text-muted)] text-sm p-8 text-center">
                                {/* eslint-disable-next-line i18next/no-literal-string */}
                                <span className="material-symbols-outlined text-4xl mb-2 opacity-50">inventory_2</span>
                                {/* eslint-enable i18next/no-literal-string */}
                                {t('putaway.noItemsPending')}
                            </div>
                        ) : (
                            <div className="flex flex-col gap-2">
                                {pendingLines.map(line => (
                                    <div 
                                        key={line.id}
                                        onClick={() => setSelectedLine(line)}
                                        className={`p-3 rounded-lg border cursor-pointer transition-colors ${selectedLine?.id === line.id ? 'bg-[var(--bg-secondary-hover)] border-[var(--accent)]' : 'border-[var(--border)] hover:bg-[var(--bg-card-hover)]'}`}
                                    >
                                        <div className="flex justify-between items-start mb-1">
                                            <div className="font-bold text-[var(--text-primary)] text-sm">{line.productName}</div>
                                            <div className="font-bold text-[var(--text-primary)] text-sm">{parseFloat(line.quantity).toLocaleString()}</div>
                                        </div>
                                        <div className="flex flex-wrap items-center gap-1.5 text-[11px] text-[var(--text-secondary)]">
                                            {line.sourceType === 'sales_return' ? (
                                                <span className="font-bold text-[var(--warning)] uppercase">{t('putaway.return')}</span>
                                            ) : (
                                                <span className="font-bold text-[var(--success)] uppercase">{t('putaway.receipt')}</span>
                                            )}
                                            <span className="text-[var(--text-muted)]">ΓÇó</span>
                                            <span className="uppercase tracking-wider">{line.productNumber}</span>
                                            <span className="text-[var(--text-muted)]">ΓÇó</span>
                                            <span>{t('putaway.ref', { ref: line.referenceNumber })}</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </>
            }
            detailPane={
                <>
                    <div className="hidden lg:block px-4 py-3 border-b border-[var(--border)] bg-[var(--bg-secondary)]">
                        <h2 className="text-sm font-bold text-[var(--text-primary)] uppercase tracking-wider">{t('putaway.action')}</h2>
                    </div>
                    {actionFormContent}
                </>
            }
        />
    );
}

'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import StateBadge from '@/components/StateBadge';
import { ValidState } from '@/types/states';
import { reportError } from '@/lib/api';
import * as api from '@modbm/sdk';
import { useSettings } from '@/components/SettingsProvider';
import { toast } from 'react-hot-toast';
import Link from 'next/link';
import MasterDetailLayout from '@/components/shared/MasterDetailLayout';
import { getErrorMessage } from '@modbm/shared';

// ΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface ShippingOrder {
    id: string;
    orderNumber: string;
    name: string;
    customerName: string;
    customerOrderNumber: string;
    stateCode: string;
    createdOn: string | null;
    createdBy: string;
    currencyCode: string | null;
    shippabilityStatus: 'ready' | 'partial';
    totalShippableLines: number;
    totalLines: number;
}

interface ShippingLine {
    salesOrderLineId: string;
    lineNumber: number;
    productId: string;
    productNumber: string;
    productDescription: string;
    isPhysical: boolean;
    quantity: string;
    quantityPicked: string;
    quantityShipped: string;
    availableToShip: string;
}

interface ShipmentSummary {
    shipmentId: string;
    shipmentNumber: string;
    stateCode: string;
    notes: string | null;
    trackingNumber: string | null;
    createdOn: string;
    lineCount: number;
}

interface ShippingContext {
    lines: ShippingLine[];
    shipments: ShipmentSummary[];
}

// ΓöÇΓöÇ Page ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export default function ShippingPage() {
    const t = useTranslations('shipping');
    const tCommon = useTranslations('common');
    useDocumentTitle(t('title'));
    const { app } = useSettings();

    // Location
    const [locations, setLocations] = useState<any[]>([]);
    const [selectedLocationId, setSelectedLocationId] = useState<string>('');

    // Queue
    const [orders, setOrders] = useState<ShippingOrder[]>([]);
    const [selectedOrder, setSelectedOrder] = useState<ShippingOrder | null>(null);
    const [loadingOrders, setLoadingOrders] = useState(false);
    const [activeTab, setActiveTab] = useState<'ready' | 'partial'>('ready');

    // Context
    const [context, setContext] = useState<ShippingContext | null>(null);
    const [loadingContext, setLoadingContext] = useState(false);

    // Form
    const [shipQtys, setShipQtys] = useState<Record<string, string>>({});
    const [notes, setNotes] = useState('');
    const [trackingNumber, setTrackingNumber] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // ΓöÇΓöÇ Locations ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    useEffect(() => {
        api.inventoryControllerFindAllLocations({} )
            .then((response) => {
                const res = response.data as any;
                const locs = Array.isArray(res) ? res : (res.data || []);
                setLocations(locs);
                if (locs.length > 0) {
                    const defaultLocId = app?.defaultFulfillmentLocationId || locs[0].locationId;
                    setSelectedLocationId(defaultLocId);
                }
            })
            .catch(err => reportError(err, 'Failed to load locations'));
    }, [app?.defaultFulfillmentLocationId]);

    // ΓöÇΓöÇ Queue ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    const loadOrders = useCallback(() => {
        setLoadingOrders(true);
        const params: any = {};
        if (selectedLocationId) params.locationId = selectedLocationId;

        api.orderPickingControllerGetShippingQueue(params)
            .then(response => {
                setOrders(response.data as ShippingOrder[] || []);
            }).catch(err => {
                reportError(err, t('errors.failedToLoadOrdersError'));
                setOrders([]);
            })
            .finally(() => setLoadingOrders(false));
    }, [selectedLocationId, t]);

    useEffect(() => {
        loadOrders();
    }, [loadOrders]);

    const filteredOrders = useMemo(() => {
        return orders.filter(o => o.shippabilityStatus === activeTab);
    }, [orders, activeTab]);

    // ΓöÇΓöÇ Context ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    const loadContext = useCallback(() => {
        if (!selectedOrder) {
            setContext(null);
            return;
        }

        setLoadingContext(true);
        setError(null);
        api.orderPickingControllerGetShippingContext(selectedOrder.id)
            .then((response) => {
                const data = response.data ;
                setContext(data as unknown as ShippingContext);
                // Pre-fill ship quantities with available-to-ship
                const defaults: Record<string, string> = {};
                data.lines.forEach((line: ShippingLine) => {
                    const available = parseFloat(line.availableToShip);
                    if (available > 0) {
                        defaults[line.salesOrderLineId] = String(available);
                    }
                });
                setShipQtys(defaults);
                setNotes('');
                setTrackingNumber('');
            })
            .catch(err => setError(getErrorMessage(err)))
            .finally(() => setLoadingContext(false));
    }, [selectedOrder]);

    useEffect(() => {
        loadContext();
    }, [loadContext]);

    // ΓöÇΓöÇ Mutations ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    const handleCreateShipment = async () => {
        if (!selectedOrder || !context) return;

        const lines = context.lines
            .filter(l => {
                const qty = parseFloat(shipQtys[l.salesOrderLineId] || '0');
                return qty > 0;
            })
            .map(l => ({
                salesOrderLineId: l.salesOrderLineId,
                quantityShipped: shipQtys[l.salesOrderLineId],
            }));

        if (lines.length === 0) {
            setError(t('errors.atLeastOneLineError'));
            return;
        }

        setIsSubmitting(true);
        setError(null);

        try {
            await api.orderShipmentsControllerCreateShipment(selectedOrder.id, {
                notes: notes || undefined,
                trackingNumber: trackingNumber || undefined,
                lines,
            });
            toast.success(t('toasts.shipmentCreated'));
            await loadContext();
            loadOrders();
        } catch (err: unknown) {
            setError(getErrorMessage(err) || t('errors.failedToCreateError'));
        } finally {
            setIsSubmitting(false);
        }
    };

    // ΓöÇΓöÇ Computed ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    const shippableLines = useMemo(() => {
        if (!context) return [];
        return context.lines.filter(l => parseFloat(l.availableToShip) > 0);
    }, [context]);

    const totalShippable = shippableLines.length;
    const totalLines = context?.lines.filter(l => l.isPhysical).length ?? 0;

    const actionFormContent = (
        <>
            {!selectedOrder ? (
                <div className="flex flex-col items-center justify-center h-full text-[var(--text-muted)] text-sm p-8 text-center">
                    {/* eslint-disable-next-line i18next/no-literal-string */}
                    <span className="material-symbols-outlined text-4xl mb-2 opacity-50">local_shipping</span>
                    {/* eslint-enable i18next/no-literal-string */}
                    {t('selectOrder')}
                </div>
            ) : loadingContext ? (
                <div className="flex items-center justify-center h-full text-[var(--text-muted)] text-sm">
                    {t('loadingOrder')}
                </div>
            ) : context ? (
                <>
                    {/* Header */}
                    <div className="px-4 py-3 border-b border-[var(--border)] bg-[var(--bg-secondary)] flex justify-between items-center">
                        <h2 className="text-sm text-[var(--text-primary)] uppercase tracking-wider truncate mr-4 flex items-center gap-4">
                            <Link href={`/sales-orders/${selectedOrder.id}`} className="font-bold shrink-0 hover:text-[var(--accent)] hover:underline transition-colors">
                                {selectedOrder.orderNumber}
                            </Link>
                            <span className="text-[var(--text-muted)] opacity-50">&middot;</span>
                            <span className="truncate">{selectedOrder.name || t('noName')}</span>
                            <span className="text-[var(--text-muted)] opacity-50">&middot;</span>
                            <span className="truncate">{selectedOrder.customerName}</span>
                        </h2>
                        <div className="flex items-center shrink-0">
                            <span className="bg-[var(--accent)] text-white text-xs font-bold px-2 py-0.5 rounded-full">
                                {totalShippable} / {totalLines}
                            </span>
                        </div>
                    </div>

                    <div className="flex-1 overflow-y-auto p-6">
                        <div className="flex flex-col h-full w-full">
                            {error && (
                                <div className="mb-4 p-3 bg-red-50 border border-red-200 text-red-700 text-sm rounded-md flex items-center gap-2">
                                    {/* eslint-disable-next-line i18next/no-literal-string */}
                                    <span className="material-symbols-outlined text-sm">error</span>
                                    {/* eslint-enable i18next/no-literal-string */}
                                    {error}
                                </div>
                            )}

                            <div className="space-y-8">
                                {/* Ship Form Header Fields */}
                                <div className="flex flex-col sm:flex-row gap-4">
                                    <div className="flex-1">
                                        <label className="text-xs font-bold text-[var(--text-muted)] uppercase tracking-wider mb-1 block">
                                            {t('columns.trackingNumber')}
                                        </label>
                                        <input
                                            type="text"
                                            value={trackingNumber}
                                            onChange={e => setTrackingNumber(e.target.value)}
                                            placeholder={t('placeholders.tracking')}
                                            className="input w-full"
                                        />
                                    </div>
                                    <div className="flex-1">
                                        <label className="text-xs font-bold text-[var(--text-muted)] uppercase tracking-wider mb-1 block">
                                            {t('columns.notes')}
                                        </label>
                                        <input
                                            type="text"
                                            value={notes}
                                            onChange={e => setNotes(e.target.value)}
                                            placeholder={t('placeholders.notes')}
                                            className="input w-full"
                                        />
                                    </div>
                                </div>

                                {/* Lines Table */}
                                <div>
                                    {/* Mobile Cards */}
                                    <div className="lg:hidden flex flex-col gap-3">
                                        {context.lines.filter(l => l.isPhysical).map(line => {
                                            const available = parseFloat(line.availableToShip);
                                            const hasStock = available > 0;
                                            return (
                                                <div key={line.salesOrderLineId} className={`p-4 bg-[var(--bg-card)] border border-[var(--border)] rounded-lg ${!hasStock ? 'opacity-50' : ''}`}>
                                                    <div className="flex justify-between items-start mb-2">
                                                        <div>
                                                            <div className="font-bold">{line.productNumber}</div>
                                                            <div className="text-xs text-[var(--text-muted)] mt-0.5">{line.productDescription}</div>
                                                        </div>
                                                        <div className="text-right flex flex-col items-end">
                                                            <div className="text-xs font-bold text-[var(--text-muted)] uppercase mb-1">{t('columns.qtyToShip')}</div>
                                                            {hasStock ? (
                                                                <input
                                                                    type="number"
                                                                    min="0"
                                                                    step="0.01"
                                                                    max={available}
                                                                    value={shipQtys[line.salesOrderLineId] || ''}
                                                                    onChange={(e) => setShipQtys(prev => ({
                                                                        ...prev,
                                                                        [line.salesOrderLineId]: e.target.value
                                                                    }))}
                                                                    className="input w-24 text-right"
                                                                />
                                                            ) : (
                                                                <span className="text-[var(--text-muted)]">-</span>
                                                            )}
                                                        </div>
                                                    </div>
                                                    
                                                    <div className="grid grid-cols-4 gap-2 mt-4 pt-3 border-t border-[var(--border)]">
                                                        <div>
                                                            <div className="text-[10px] text-[var(--text-muted)] uppercase mb-0.5">{t('columns.ordered')}</div>
                                                            <div className="text-xs font-medium">{parseFloat(line.quantity).toLocaleString()}</div>
                                                        </div>
                                                        <div>
                                                            <div className="text-[10px] text-[var(--text-muted)] uppercase mb-0.5">{t('columns.picked')}</div>
                                                            <div className="text-xs font-medium">{parseFloat(line.quantityPicked).toLocaleString()}</div>
                                                        </div>
                                                        <div>
                                                            <div className="text-[10px] text-[var(--text-muted)] uppercase mb-0.5">{t('columns.shipped')}</div>
                                                            <div className="text-xs font-medium">{parseFloat(line.quantityShipped).toLocaleString()}</div>
                                                        </div>
                                                        <div className="text-right">
                                                            <div className="text-[10px] text-[var(--text-muted)] uppercase mb-0.5">{t('columns.available')}</div>
                                                            <div className={`text-xs font-semibold ${hasStock ? 'text-[var(--success)]' : 'text-[var(--text-muted)]'}`}>
                                                                {available.toLocaleString()}
                                                            </div>
                                                        </div>
                                                    </div>
                                                </div>
                                            );
                                        })}
                                        {context.lines.filter(l => l.isPhysical).length === 0 && (
                                            <div className="py-6 text-center text-sm text-[var(--text-muted)] border border-[var(--border)] rounded-lg">
                                                {t('noPhysicalLines')}
                                            </div>
                                        )}
                                    </div>

                                    {/* Desktop Table */}
                                    <table className="table-lines hidden lg:table">
                                        <thead>
                                            <tr>
                                                <th>{t('columns.product')}</th>
                                                <th style={{ textAlign: 'right' }}>{t('columns.ordered')}</th>
                                                <th style={{ textAlign: 'right' }}>{t('columns.picked')}</th>
                                                <th style={{ textAlign: 'right' }}>{t('columns.shipped')}</th>
                                                <th style={{ textAlign: 'right' }}>{t('columns.available')}</th>
                                                <th style={{ textAlign: 'right' }}>{t('columns.qtyToShip')}</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            {context.lines.filter(l => l.isPhysical).map(line => {
                                                const available = parseFloat(line.availableToShip);
                                                const hasStock = available > 0;
                                                return (
                                                    <tr key={line.salesOrderLineId} className={!hasStock ? 'opacity-50' : ''}>
                                                        <td>
                                                            <div className="font-bold">{line.productNumber}</div>
                                                            <div className="text-xs text-[var(--text-muted)] truncate max-w-[250px]">{line.productDescription}</div>
                                                        </td>
                                                        <td style={{ textAlign: 'right' }}>
                                                            {parseFloat(line.quantity).toLocaleString()}
                                                        </td>
                                                        <td style={{ textAlign: 'right' }}>
                                                            {parseFloat(line.quantityPicked).toLocaleString()}
                                                        </td>
                                                        <td style={{ textAlign: 'right' }}>
                                                            {parseFloat(line.quantityShipped).toLocaleString()}
                                                        </td>
                                                        <td style={{ textAlign: 'right' }}>
                                                            <span className={hasStock ? 'font-semibold text-[var(--success)]' : 'text-[var(--text-muted)]'}>
                                                                {available.toLocaleString()}
                                                            </span>
                                                        </td>
                                                        <td style={{ textAlign: 'right' }}>
                                                            {hasStock ? (
                                                                <div className="flex justify-end">
                                                                    <input
                                                                        type="number"
                                                                        min="0"
                                                                        step="0.01"
                                                                        max={available}
                                                                        value={shipQtys[line.salesOrderLineId] || ''}
                                                                        onChange={(e) => setShipQtys(prev => ({
                                                                            ...prev,
                                                                            [line.salesOrderLineId]: e.target.value
                                                                        }))}
                                                                        className="input"
                                                                        style={{ width: '80px', textAlign: 'right', padding: '2px 6px', fontSize: '13px' }}
                                                                    />
                                                                </div>
                                                            ) : (
                                                                <span className="text-[var(--text-muted)]">-</span>
                                                            )}
                                                        </td>
                                                    </tr>
                                                );
                                            })}
                                            {context.lines.filter(l => l.isPhysical).length === 0 && (
                                                <tr>
                                                    <td colSpan={6} className="py-6 text-center text-sm text-[var(--text-muted)]">
                                                        {t('noPhysicalLines')}
                                                    </td>
                                                </tr>
                                            )}
                                        </tbody>
                                    </table>
                                </div>

                                {/* Create Button */}
                                <div className="flex justify-end">
                                    <button
                                        type="button"
                                        onClick={handleCreateShipment}
                                        disabled={isSubmitting || shippableLines.length === 0}
                                        className="btn btn-primary"
                                    >
                                        {t('buttons.createShipment')}
                                    </button>
                                </div>

                                {/* Existing Shipments */}
                                {context.shipments.length > 0 && (
                                    <div>
                                        <h4 className="section-heading !mb-4 !text-[var(--text-muted)]">{t('existingShipments')}</h4>
                                        <div className="flex flex-col gap-2">
                                            {context.shipments.map(shipment => (
                                                <div
                                                    key={shipment.shipmentId}
                                                    className="flex flex-col sm:flex-row sm:items-center justify-between p-4 rounded-lg border border-[var(--border)] hover:bg-[var(--bg-card-hover)] transition-colors gap-4 mt-2"
                                                >
                                                    <div className="flex items-start sm:items-center gap-3">
                                                        {/* eslint-disable-next-line i18next/no-literal-string */}
                                                        <span className="material-symbols-outlined text-[var(--text-muted)] text-xl mt-0.5 sm:mt-0 shrink-0">inventory_2</span>
                                                        {/* eslint-enable i18next/no-literal-string */}
                                                        <div className="min-w-0">
                                                            <Link href={`/shipments/${shipment.shipmentId}`} className="font-bold text-base text-[var(--text-primary)] hover:text-[var(--accent)] hover:underline break-all sm:break-normal">
                                                                {shipment.shipmentNumber}
                                                            </Link>
                                                            <div className="text-xs text-[var(--text-muted)] mt-1">
                                                                {new Date(shipment.createdOn).toLocaleDateString()} ┬╖ {t('shipmentLines', { count: shipment.lineCount })}
                                                                {shipment.trackingNumber && (
                                                                    <span> ┬╖ {shipment.trackingNumber}</span>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                    <div className="flex items-center justify-between sm:justify-end gap-3 pl-8 sm:pl-0 w-full sm:w-auto">
                                                        <StateBadge state={shipment.stateCode as ValidState} />
                                                        <button
                                                            type="button"
                                                            className="btn btn-secondary btn-sm flex items-center"
                                                            onClick={async () => {
                                                                try {
                                                                    const { reportError } = await import('@/lib/api');
                                                                    const api = await import('@modbm/sdk');
                                                                    const res = await api.reportsControllerRunHook('shipping-docket', { shipmentId: shipment.shipmentId }, { id: shipment.shipmentId, context: 'shipment' });
                                                                    const blob = res.data as Blob;
                                                                    const url = URL.createObjectURL(blob);
                                                                    window.open(url, '_blank');
                                                                } catch (err) {
                                                                    reportError(err, 'Failed to generate shipping docket');
                                                                    toast.error(t('errors.failedToGenerateDocketError'));
                                                                }
                                                            }}
                                                        >
                                                            <span className="font-medium">{t('docketPdf')}</span>
                                                        </button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </>
            ) : null}
        </>
    );

    // ΓöÇΓöÇ Render ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    return (
        <MasterDetailLayout
            title={t('title')}
            controls={
                <>
                    <span className="text-sm font-semibold text-[var(--text-muted)] hidden sm:inline">{tCommon('location')}:</span>
                    <select
                        value={selectedLocationId}
                        onChange={(e) => setSelectedLocationId(e.target.value)}
                        className="input text-sm w-full sm:w-48"
                    >
                        {locations.map(loc => (
                            <option key={loc.locationId} value={loc.locationId}>
                                {loc.code} - {loc.name}
                            </option>
                        ))}
                    </select>
                </>
            }
            masterWidthClass="lg:w-1/3"
            isDetailOpen={!!selectedOrder}
            onCloseDetail={() => { setSelectedOrder(null); setContext(null); }}
            detailTitle={selectedOrder ? selectedOrder.orderNumber : undefined}
            masterPane={
                <>
                    <div className="flex lg:border-b lg:border-[var(--border)] lg:bg-[var(--bg-secondary)] text-xs font-bold pt-1 lg:px-1 gap-1 border-b border-[var(--border)]">
                        <button 
                            className={`flex-1 py-2.5 px-2 text-center border-b-2 rounded-t-md transition-colors ${activeTab === 'ready' ? 'border-[var(--success)] text-[var(--success)] bg-[var(--bg-card)]' : 'border-transparent text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)]'}`}
                            onClick={() => setActiveTab('ready')}
                        >
                            {t('tabs.ready')} <span className="ml-1 opacity-75 font-normal">({orders.filter(o => o.shippabilityStatus === 'ready').length})</span>
                        </button>
                        <button 
                            className={`flex-1 py-2.5 px-2 text-center border-b-2 rounded-t-md transition-colors ${activeTab === 'partial' ? 'border-[var(--warning)] text-[var(--warning)] bg-[var(--bg-card)]' : 'border-transparent text-[var(--text-muted)] hover:text-[var(--text-primary)] hover:bg-[var(--bg-card-hover)]'}`}
                            onClick={() => setActiveTab('partial')}
                        >
                            {t('tabs.partial')} <span className="ml-1 opacity-75 font-normal">({orders.filter(o => o.shippabilityStatus === 'partial').length})</span>
                        </button>
                    </div>
                    
                    <div className="flex-1 overflow-y-auto p-2 pb-24 lg:pb-2 bg-[var(--bg-card)] lg:bg-transparent rounded-b-md lg:rounded-none">
                        {loadingOrders ? (
                            <div className="flex items-center justify-center h-full text-[var(--text-muted)] text-sm">
                                {tCommon('loading')}
                            </div>
                        ) : filteredOrders.length === 0 ? (
                            <div className="flex flex-col items-center justify-center h-full text-[var(--text-muted)] text-sm p-8 text-center">
                                {/* eslint-disable-next-line i18next/no-literal-string */}
                                <span className="material-symbols-outlined text-4xl mb-2 opacity-50">inbox</span>
                                {t('noOrders', { tab: activeTab })}
                            </div>
                        ) : (
                            <div className="flex flex-col gap-2">
                                {filteredOrders.map(order => (
                                    <div 
                                        key={order.id}
                                        onClick={() => setSelectedOrder(order)}
                                        className={`p-3 rounded-lg border cursor-pointer transition-colors ${selectedOrder?.id === order.id ? 'bg-[var(--bg-secondary-hover)] border-[var(--accent)]' : 'border-[var(--border)] hover:bg-[var(--bg-card-hover)]'}`}
                                    >
                                        <div className="flex justify-between items-start mb-1">
                                            <div className="flex items-center gap-2">
                                                {/* eslint-disable-next-line i18next/no-literal-string */}
                                                <span className={`material-symbols-outlined indicator-icon shrink-0 ${order.shippabilityStatus === 'ready' ? 'text-[var(--success)]' : 'text-[var(--warning)]'}`} style={{ fontVariationSettings: "'FILL' 1" }}>fiber_manual_record</span>
                                                {/* eslint-enable i18next/no-literal-string */}
                                                <div className="font-bold text-[var(--text-primary)] text-sm">{order.orderNumber}</div>
                                            </div>
                                            <StateBadge state={order.stateCode as ValidState} />
                                        </div>
                                        <div className="text-xs font-bold text-[var(--text-secondary)] mb-1 pl-7">{order.customerName}</div>
                                        <div className="flex items-center justify-between pl-7">
                                            <div className="text-xs text-[var(--text-muted)] truncate">{order.name || order.customerOrderNumber}</div>
                                            <span className="text-[10px] font-bold bg-[var(--bg-secondary)] text-[var(--text-muted)] px-1.5 py-0.5 rounded-full shrink-0 ml-2">
                                                {order.totalShippableLines}/{order.totalLines}
                                            </span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </>
            }
            detailPane={actionFormContent}
        />
    );
}

'use client';

import { useState, useEffect } from 'react';
import SlideOver from '@/components/shared/SlideOver';
import { useTranslations } from 'next-intl';
import LocationSelect from '@/components/shared/LocationSelect';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import * as api from '@modbm/sdk';
import { toast } from 'react-hot-toast';
import { getErrorMessage } from '@modbm/shared';

interface LineItem {
  productId: string;
  productNumber: string;
  name: string;
  quantity: number;
}

interface CreateTransferSlideOverProps {
  open: boolean;
  onClose: () => void;
  onCreated: () => void;
}

export default function CreateTransferSlideOver({ open, onClose, onCreated }: CreateTransferSlideOverProps) {
  const t = useTranslations('transfers');
  const tCommon = useTranslations('common');
  
  const [sourceLocationId, setSourceLocationId] = useState('');
  const [destinationLocationId, setDestinationLocationId] = useState('');
  const [notes, setNotes] = useState('');
  const [lines, setLines] = useState<LineItem[]>([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (open) {
      // Reset state
      setSourceLocationId('');
      setDestinationLocationId('');
      setNotes('');
      setLines([]);
    }
  }, [open]);

  const handleAddProduct = (product: any) => {
    // Check if product already exists
    const existingIndex = lines.findIndex(l => l.productId === product.productId);
    if (existingIndex >= 0) {
      updateLine(existingIndex, 'quantity', lines[existingIndex].quantity + 1);
    } else {
      setLines([...lines, { 
        productId: product.productId, 
        productNumber: product.productNumber,
        name: product.name,
        quantity: 1 
      }]);
    }
  };

  const handleRemoveLine = (index: number) => {
    setLines(lines.filter((_, i) => i !== index));
  };

  const updateLine = (index: number, field: 'quantity', value: number) => {
    const newLines = [...lines];
    newLines[index] = { ...newLines[index], [field]: value };
    setLines(newLines);
  };

  const handleSubmit = async () => {
    if (!sourceLocationId || !destinationLocationId) {
      toast.error('Source and destination locations are required.');
      return;
    }
    
    if (sourceLocationId === destinationLocationId) {
      toast.error('Source and destination locations must be different.');
      return;
    }

    const validLines = lines
      .filter(l => l.productId && l.quantity > 0)
      .map(l => ({
        productId: l.productId,
        quantity: l.quantity.toString()
      }));
    
    try {
      setIsSubmitting(true);
      await api.transfersControllerCreate({
        sourceLocationId,
        destinationLocationId,
        notes,
        lines: validLines
      });
      onCreated();
      onClose();
    } catch (e: unknown) {
      toast.error(getErrorMessage(e) || 'Failed to create transfer order');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <SlideOver
      isOpen={open}
      onClose={onClose}
      title={t('createSlideOver.title')}
      subtitle={t('createSlideOver.subtitle')}
      width="max-w-3xl"
      footer={
        <div className="flex items-center justify-end gap-3 w-full">
          <button type="button" className="btn btn-ghost" onClick={onClose} disabled={isSubmitting}>
            {tCommon('cancel')}
          </button>
          <button
            onClick={handleSubmit}
            disabled={isSubmitting || !sourceLocationId || !destinationLocationId}
            className="btn btn-primary bg-[#006b5c] hover:bg-[#005246] border-none text-white shadow-sm"
          >
            {isSubmitting ? (
              <><span className="loading loading-spinner loading-sm mr-2" />{tCommon('saving')}</>
            ) : (
              t('buttons.createTransfer')
            )}
          </button>
        </div>
      }
    >
      <div className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              {t('columns.sourceLocation')} *
            </label>
            <LocationSelect
              className="w-full"
              value={sourceLocationId}
              onChange={(val) => setSourceLocationId(val || '')}
              placeholder={t('placeholders.selectSourceLocation')}
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              {t('columns.destinationLocation')} *
            </label>
            <LocationSelect
              className="w-full"
              value={destinationLocationId}
              onChange={(val) => setDestinationLocationId(val || '')}
              placeholder={t('placeholders.selectDestinationLocation')}
              required
            />
          </div>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            {t('columns.notes')}
          </label>
          <textarea
            className="input w-full"
            rows={3}
            placeholder={t('placeholders.notes')}
            value={notes}
            onChange={e => setNotes(e.target.value)}
          />
        </div>

        <div className="border-t border-gray-200 pt-6">
          <div className="flex items-center justify-between mb-4">
            <h4 className="font-medium text-lg">{t('lineItems')}</h4>
            <ProductSearchInput
              onSelect={handleAddProduct}
              placeholder="Search product..."
              style={{ width: 240 }}
              fulfillmentLocationId={sourceLocationId}
            />
          </div>

          <div className="space-y-3">
            {lines.map((line, index) => (
              <div key={index} className="flex gap-3 items-center">
                <div className="flex-1 text-sm">
                  <span className="font-semibold text-gray-900">{line.productNumber}</span>
                  <span className="text-gray-500 ml-2">{line.name}</span>
                </div>
                <div className="w-32">
                  <input
                    type="number"
                    min="1"
                    className="input w-full"
                    value={line.quantity || ''}
                    onChange={e => updateLine(index, 'quantity', parseFloat(e.target.value))}
                  />
                </div>
                <button
                  className="text-gray-400 hover:text-red-500"
                  onClick={() => handleRemoveLine(index)}
                >
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined">delete</span>
                  {/* eslint-enable i18next/no-literal-string */}
                </button>
              </div>
            ))}
            {lines.length === 0 && (
              <div className="text-sm text-gray-500 italic">{t('noLinesAdded')}</div>
            )}
          </div>
        </div>
      </div>
    </SlideOver>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { useDocumentTitle } from '@/hooks/useDocumentTitle';
import EntityHeader from '@/components/shared/EntityHeader';
import DetailsLayout from '@/components/shared/DetailsLayout';
import StateBadge from '@/components/StateBadge';
import ActivityTimeline from '@/components/shared/ActivityTimeline';
import { ValidState } from '@/types/states';
import { useTransferOrder } from './useTransferOrder';
import { TRANSFER_ORDER_STATE } from '@modbm/shared';
import ProductSearchInput from '@/components/shared/ProductSearchInput';
import { MobileCardField } from '@/components/shared/DataTable';

export default function TransferDetailsClient({ id }: { id: string }) {
  const router = useRouter();
  const tCommon = useTranslations('common');
  const tTransfers = useTranslations('transfers');

  const {
    order,
    loading,
    error,
    saving,
    clearError,
    editNotes,
    setEditNotes,
    saveHeader,
    addLine,
    updateLine,
    removeLine,
    shipOrder,
    cancelOrder,
  } = useTransferOrder(id);

  useDocumentTitle(order ? tTransfers('transferTitle', { number: order.orderNumber }) : null);

  if (loading) {
    return (
      <div className="flex items-center justify-center flex-1">
        <p style={{ color: 'var(--text-muted)' }}>{tCommon('loading')}</p>
      </div>
    );
  }

  if (!order) {
    return (
      <div className="flex flex-col items-center justify-center flex-1">
        <p className="text-lg mb-2" style={{ color: 'var(--danger)' }}>
          {error || tTransfers('notFound')}
        </p>
        <button className="btn btn-secondary" onClick={() => router.push('/inventory/transfers')}>
          {tTransfers('backToTransfers')}
        </button>
      </div>
    );
  }

  const isEditable = order.stateCode === TRANSFER_ORDER_STATE.CONFIRMED;
  const canCancel = [
    TRANSFER_ORDER_STATE.CONFIRMED,
    TRANSFER_ORDER_STATE.PICKING,
    TRANSFER_ORDER_STATE.SHIPPED,
  ].includes(order.stateCode );
  const headerDirty = order.notes !== editNotes;

  const handleCancel = async () => {
    if (window.confirm(tTransfers('cancelConfirm'))) {
      await cancelOrder();
    }
  };

  return (
    <DetailsLayout
      header={
        <EntityHeader
          title={order.orderNumber}
          subtitle={tTransfers('subtitleFlow', {
            source: order.sourceLocationName || order.sourceLocationId || '',
            destination: order.destinationLocationName || order.destinationLocationId || ''
          })}
          onBack={() => router.push('/inventory/transfers')}
          isSaving={saving}
          badges={<StateBadge state={order.stateCode as ValidState} />}
          actions={
            <div className="flex gap-2">
              {canCancel && (
                <button
                  className="btn btn-danger btn-sm"
                  onClick={handleCancel}
                  disabled={saving}
                >
                  {/* eslint-disable-next-line i18next/no-literal-string */}
                  <span className="material-symbols-outlined mr-1" style={{ fontSize: 16 }}>close</span>
                  {/* eslint-enable i18next/no-literal-string */}
                  {tCommon('cancel')}
                </button>
              )}
            </div>
          }
        />
      }
    >
      <div className="flex flex-col gap-3">
        {error && (
          <div
            className="px-4 py-3 rounded-lg text-sm"
            style={{
              background: 'rgba(239, 68, 68, 0.1)',
              border: '1px solid rgba(239, 68, 68, 0.3)',
              color: '#f87171',
            }}
          >
            {error}
            <button className="ml-3 text-xs underline" onClick={clearError}>{tCommon('dismiss')}</button>
          </div>
        )}

        <div className="card">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.sourceLocation')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {order.sourceLocationName || order.sourceLocationId}
              </p>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.destinationLocation')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {order.destinationLocationName || order.destinationLocationId}
              </p>
            </div>
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.createdOn')}
              </label>
              <p className="text-sm" style={{ fontWeight: 500, paddingTop: 6 }}>
                {new Date(order.createdOn).toLocaleString()} {tCommon('by')} {order.createdBy}
              </p>
            </div>
            <div className="col-span-2">
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--text-muted)' }}>
                {tTransfers('columns.notes')}
              </label>
              <input
                className="input w-full"
                value={editNotes}
                onChange={(e) => setEditNotes(e.target.value)}
                onBlur={saveHeader}
                disabled={!isEditable}
                placeholder={tTransfers('placeholders.notes')}
              />
            </div>
          </div>
        </div>

        <div className="card">
          <div className="flex items-center justify-between mb-4">
            <h3 className="section-heading">
              {/* eslint-disable-next-line i18next/no-literal-string */}
              <span className="material-symbols-outlined">inventory_2</span>
              {/* eslint-enable i18next/no-literal-string */}
              {tTransfers('lineItems')}
            </h3>
            {isEditable && (
              <ProductSearchInput
                onSelect={(p: any) => addLine(p.productId, 1)}
                placeholder={tTransfers('placeholders.searchProduct')}
                style={{ width: 240 }}
              />
            )}
          </div>

          <div className="hidden lg:block overflow-x-auto w-full">
            <table className="table-lines">
            <thead>
              <tr>
                <th>{tTransfers('columns.product')}</th>
                <th>{tTransfers('columns.description')}</th>
                <th style={{ width: 120, textAlign: 'right' }}>{tTransfers('columns.ordered')}</th>
                <th style={{ width: 120, textAlign: 'right' }}>{tTransfers('columns.shipped')}</th>
                <th style={{ width: 120, textAlign: 'right' }}>{tTransfers('columns.received')}</th>
                {isEditable && <th style={{ width: 50 }}></th>}
              </tr>
            </thead>
            <tbody>
              {order.lines?.map((line: any) => (
                <tr key={line.transferOrderLineId}>
                  <td style={{ fontWeight: 600, fontSize: 12 }}>
                    {line.productNumber || 'ΓÇö'}
                  </td>
                  <td>{line.productDescription || 'ΓÇö'}</td>
                  {isEditable ? (
                    <td style={{ textAlign: 'right' }}>
                      <input
                        className="input"
                        type="number"
                        min="1"
                        step="1"
                        style={{ width: '100%', textAlign: 'right' }}
                        defaultValue={line.quantity}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value);
                          if (val > 0 && val !== parseFloat(line.quantity)) {
                            updateLine(line.transferOrderLineId, val);
                          }
                        }}
                      />
                    </td>
                  ) : (
                    <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                      {line.quantity}
                    </td>
                  )}
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                    {line.quantityShipped || 0}
                  </td>
                  <td style={{ textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                    {line.quantityReceived || 0}
                  </td>
                  {isEditable && (
                    <td>
                      <button
                        className="btn btn-danger btn-sm"
                        onClick={() => removeLine(line.transferOrderLineId)}
                        title={tTransfers('removeLine')}
                      >
                        <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} />
                      </button>
                    </td>
                  )}
                </tr>
              ))}
              {(!order.lines || order.lines.length === 0) && (
                <tr>
                  <td
                    colSpan={isEditable ? 6 : 5}
                    style={{ textAlign: 'center', color: 'var(--text-muted)', padding: '20px 0' }}
                  >
                    {tTransfers('noLineItems')}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
          </div>
          <div className="lg:hidden flex flex-col gap-3 w-full">
            {order.lines?.map((line: any, idx: number) => (
              <div key={line.transferOrderLineId} className="bg-[var(--bg-card)] rounded-xl border border-[var(--border)] p-4 flex flex-col shadow-sm">
                <div className="flex justify-between items-start gap-2 mb-2">
                  <div className="font-semibold text-sm text-[var(--accent)]">
                    {line.productNumber || 'ΓÇö'}
                  </div>
                  <div className="text-xs text-slate-500 bg-slate-100 px-2 py-0.5 rounded font-medium">#{idx + 1}</div>
                </div>
                <div className="text-sm text-slate-600 font-medium mb-3">
                  {line.productDescription || 'ΓÇö'}
                </div>
                <div className="flex flex-col gap-1 border-t border-slate-100 pt-2">
                  <MobileCardField label={tTransfers('columns.ordered')} value={
                    isEditable ? (
                      <input
                        className="input"
                        type="number"
                        min="1"
                        step="1"
                        style={{ width: '100px', textAlign: 'right', padding: '4px 8px', height: '32px' }}
                        defaultValue={line.quantity}
                        onBlur={(e) => {
                          const val = parseFloat(e.target.value);
                          if (val > 0 && val !== parseFloat(line.quantity)) {
                            updateLine(line.transferOrderLineId, val);
                          }
                        }}
                      />
                    ) : line.quantity
                  } />
                  <MobileCardField label={tTransfers('columns.shipped')} value={line.quantityShipped || 0} />
                  <MobileCardField label={tTransfers('columns.received')} value={line.quantityReceived || 0} />
                  {isEditable && (
                    <div className="flex justify-end pt-2 mt-1 border-t border-slate-50">
                      <button
                        className="btn btn-danger btn-sm"
                        onClick={() => removeLine(line.transferOrderLineId)}
                        title={tTransfers('removeLine')}
                      >
                        <span dangerouslySetInnerHTML={{ __html: '&#10005;' }} /> {tCommon('delete')}
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {(!order.lines || order.lines.length === 0) && (
              <div className="text-center py-6 text-slate-400 text-sm">
                {tTransfers('noLineItems')}
              </div>
            )}
          </div>
        </div>

        {/* Activity Timeline */}
        <div className="card">
          <ActivityTimeline events={order.events || []} />
        </div>
      </div>
    </DetailsLayout>
  );
}
